-- Clean bootstrap 022: final privilege boundary, password completion and status transitions.
CREATE OR REPLACE FUNCTION public.complete_password_setup() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth AS $$ BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=auth.uid() AND encrypted_password IS NOT NULL) THEN RAISE EXCEPTION 'Password setup incomplete'; END IF; PERFORM set_config('app.role_change_rpc','on',true); UPDATE public.user_profiles SET must_change_password=false WHERE id=auth.uid(); PERFORM public.write_audit_log('complete_password_setup','user_profiles',auth.uid(),NULL,jsonb_build_object('must_change_password',false)); END $$;
CREATE OR REPLACE FUNCTION public.transition_order_status(order_id uuid,new_status text,reason text DEFAULT NULL) RETURNS public.sales_orders LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result public.sales_orders; old_status text; allowed boolean:=false; BEGIN SELECT order_status INTO STRICT old_status FROM public.sales_orders WHERE id=order_id FOR UPDATE; allowed:=CASE old_status WHEN 'pending' THEN new_status IN('confirmed','cancelled') WHEN 'confirmed' THEN new_status IN('processing','cancelled') WHEN 'processing' THEN new_status IN('shipped','cancelled') ELSE false END; IF NOT allowed OR NOT(public.is_admin() OR public.has_role('commercial_staff','warehouse_staff')) THEN RAISE EXCEPTION 'Invalid or unauthorized transition'; END IF; UPDATE public.sales_orders SET order_status=new_status,updated_at=now() WHERE id=order_id RETURNING * INTO result; INSERT INTO public.workflow_transitions(entity_type,entity_id,from_status,to_status,reason,changed_by) VALUES('sales_order',order_id,old_status,new_status,reason,auth.uid()); RETURN result; END $$;
REVOKE INSERT,UPDATE,DELETE ON public.sales_orders,public.order_items,public.inventory_stock,public.stock_movements,public.payments,public.exchange_rates FROM authenticated;
REVOKE UPDATE,DELETE ON public.deliveries FROM authenticated;
REVOKE SELECT ON public.products FROM authenticated;
GRANT SELECT(id,sku,name,description,category_id,unit_price,currency,image_url,barcode,is_active,created_at,updated_at) ON public.products TO authenticated;
GRANT SELECT(cost_price) ON public.products TO service_role;
GRANT EXECUTE ON FUNCTION public.complete_password_setup(),public.transition_order_status(uuid,text,text) TO authenticated;
